{
  "evidence_ids": ["EV-01-SCEN-FR-001-08-01", "EV-01-SCEN-FR-001-08-02"],
  "rationale": "Launching the game displayed a puzzle board with zero moves, and a subsequent move updated the board and move count. This establishes that a player can start a puzzle session by launching a puzzle.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-002-09-01", "EV-01-SCEN-FR-002-09-02"],
  "rationale": "The game displayed a goodbye message and the process exited successfully, establishing that the session ended when the player exited the game.",
  "limitation": "Session endings after solving the puzzle or giving up were not observed.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-003-10-02"],
  "rationale": "The level was completed, and the game reported “Puzzle solved! Progress saved.” This directly supports saving progress on completion.",
  "limitation": "The saved progress was not independently read back.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-004-11-02"],
  "rationale": "After two moves in an unfinished game, the system reported “Saved progress” before exiting. This establishes a save of in-progress play; no unsafe condition was recorded.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-005-12-02"],
  "rationale": "No required obligation was established. The game displayed an untouched puzzle and reported saving progress on quit, but the record does not show preservation of a puzzle in progress or later continuation.",
  "limitation": "Quitting after changing the puzzle state and reopening it to verify that state was preserved were not observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-006-13-02"],
  "rationale": "No required restoration behaviour was observed. The game saved progress on a normal quit, not after a sudden interruption or closure.",
  "limitation": "Restoration of the last safe state after an interruption or sudden closure was not tested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-007-14-02", "EV-01-SCEN-FR-007-14-03"],
  "rationale": "An attempted move outside the board was blocked: the board, move count, and score remained unchanged. The system immediately explained the reason with “Invalid move: Move is outside the board,” and recorded no standard-error output.",
  "limitation": "Other kinds of invalid moves were not tested.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-008-15-02"],
  "rationale": "The game rejected an out-of-bounds move. The board, move count, and score remained unchanged, and the game reported saving progress on exit.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-009-16-02"],
  "rationale": "The player used the listed single-key undo command after moving. The position and move count returned to their starting values, and the score returned from 95 to 100, showing the move was undone without a score penalty.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-010-17-02"],
  "rationale": "The player restarted the puzzle with the listed single-key `r` command. The board returned to its starting state, moves reset from 1 to 0, and score returned from 95 to 100, showing no penalty in the recorded restart.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-011-18-02"],
  "rationale": "The game lists a hint command and initially displays the puzzle without a hint. It then displays the subtle suggestion “try to move right” after a command prompt, supporting a requestable hint rather than a pushed one.",
  "limitation": "The exact input that triggered the hint was not captured.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-012-19-02"],
  "rationale": "The output shows three moves processed in sequence, but none was shown to arrive while another action was being processed. No required branch was established.",
  "limitation": "Whether the system ignores, rather than queues, inputs received during an action remains untested.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-013-20-02"],
  "rationale": "Three successive moves shown within the same timestamp advance the player one space each time, with the move count increasing from 0 to 3. The recorded board state remains consistent after the repeated inputs.",
  "limitation": "The timestamps have only one-second precision, so the exact spacing of the inputs is unknown.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-014-21-02"],
  "rationale": "During one play session, the displayed puzzle state changes after each move, while the move count and score update. This establishes tracking of the session’s active puzzle state, move count, and score.",
  "limitation": "The output says progress was saved but does not show a completion time or a readback confirming it was recorded.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-015-22-02"],
  "rationale": "No complete required obligation was observed. The output shows current progress and a generic save message, but not a retained history of completed puzzles or attempts.",
  "limitation": "No completed puzzle or attempt was shown being recorded and later available as history.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-016-23-02"],
  "rationale": "The progress view shows moves made (`moves=0`). It shows a completion flag, but does not establish a view of puzzles completed. The displayed timestamp does not show time spent on the active puzzle.",
  "limitation": "Best results are not shown, and the evidence does not establish whether any were available.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-017-24-02"],
  "rationale": "The command menu includes a dedicated Progress option, and using it displays the player's completion status, moves, and score.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-018-25-02"],
  "rationale": "The game reports that stats were exported successfully, establishing the export capability.",
  "limitation": "The recorded export uses the separate 'e' command; it does not show export from the Progress or Stats area.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-019-26-01", "EV-01-SCEN-FR-019-26-02"],
  "rationale": "The game ran without configuration arguments and reported that stats were exported successfully to a JSON file. This establishes the basic-stats export capability in the recorded default run.",
  "limitation": "The exported file was not inspected, so its specific contents are unknown.",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-020-27-02"],
  "rationale": "A stats export was reported as successful, but no complete obligation was established: the evidence does not show an option to include more detailed session records or show those records in the export.",
  "limitation": "Whether detailed session records are supported, optionally selectable, or included when selected remains unknown.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-021-28-02"],
  "rationale": "After the stats export, the system displayed a clear success message that included the exported file’s full path.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-022-29-02"],
  "rationale": "The player selected the progress view using the listed `p` command, and the system displayed completion, moves, and score as progress information.",
  "limitation": "",
  "status": "observed_satisfied"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-023-30-02"],
  "rationale": "The 'p' command displays a progress view showing completion, moves, and score.",
  "limitation": "The recording does not show more detail accessible from that progress view through an additional interaction.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-024-31-02"],
  "rationale": "The game displays a score, a time, and move and completion progress, and its progress command reports those values.",
  "limitation": "The recording does not show progress across attempts to help a player see improvement, or an exercised replay of a challenge. The save message alone does not establish that progress persists.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-025-32-01", "EV-01-SCEN-FR-025-32-02"],
  "rationale": "The player completed a puzzle, and the game reported that progress was saved. Neither required obligation is established: the record does not show play without internet access or a local save.",
  "limitation": "Internet availability during play and local persistence of progress were not observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-026-33-01", "EV-01-SCEN-FR-026-33-02"],
  "rationale": "The game launched successfully with a single command and accepted a move, establishing a working launch in the recorded environment.",
  "limitation": "Installation was not exercised, and the evidence does not establish whether setup requires extra services.",
  "status": "observed_partial"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-027-34-02"],
