  "limitation": "No experienced-player condition or comparison of prominence is recorded.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-030-37-02"],
  "rationale": "No complete required obligation was established. The game reported saving progress on a normal quit, but the record does not show play resuming after an exit or interruption.",
  "limitation": "No sudden exit or interruption and subsequent resume attempt were observed.",
  "status": "not_observable"
}

{
  "evidence_ids": ["EV-01-SCEN-FR-031-38-02"],
